/**
 * MASTER TOOL TRANSLATION RESOLVER
 * Resolves translation key based on current tool's selectedLanguage.
 */
/**
 * MASTER TOOL TRANSLATION RESOLVER (22 Scheduled Indian Languages)
 * Resolves UI localization keys and dynamic precedent content across all 22 Scheduled Indian Languages.
 */
export function tTool(
  selectedLanguage: string,
  key: string,
  fallback: string,
  replacements?: Record<string, string | number>
): string {
  const rawLang = String(selectedLanguage || '').toLowerCase().trim();

  const langKeyMap: Record<string, string> = {
    hindi: 'Hindi', hinglish: 'Hindi', bilingual: 'Hindi', hi: 'Hindi', 'hi-in': 'Hindi', हिन्दी: 'Hindi',
    marathi: 'Marathi', mr: 'Marathi', 'mr-in': 'Marathi', मराठी: 'Marathi',
    gujarati: 'Gujarati', gu: 'Gujarati', 'gu-in': 'Gujarati', ગુજરાતી: 'Gujarati',
    bengali: 'Bengali', bangla: 'Bengali', bn: 'Bengali', 'bn-in': 'Bengali', বাংলা: 'Bengali',
    tamil: 'Tamil', ta: 'Tamil', 'ta-in': 'Tamil', தமிழ்: 'Tamil',
    telugu: 'Telugu', te: 'Telugu', 'te-in': 'Telugu', తెలుగు: 'Telugu',
    kannada: 'Kannada', kn: 'Kannada', 'kn-in': 'Kannada', ಕನ್ನಡ: 'Kannada',
    malayalam: 'Malayalam', ml: 'Malayalam', 'ml-in': 'Malayalam', മലയാളം: 'Malayalam',
    punjabi: 'Punjabi', pa: 'Punjabi', 'pa-in': 'Punjabi', ਪੰਜਾਬੀ: 'Punjabi',
    odia: 'Odia', oriya: 'Odia', or: 'Odia', 'or-in': 'Odia', ଓଡ଼ିଆ: 'Odia',
    urdu: 'Urdu', ur: 'Urdu', 'ur-in': 'Urdu', اردو: 'Urdu',
    assamese: 'Assamese', as: 'Assamese', অসমীয়া: 'Assamese',
    sanskrit: 'Sanskrit', sa: 'Sanskrit', संस्कृत: 'Sanskrit',
    nepali: 'Nepali', ne: 'Nepali', नेपाली: 'Nepali',
    konkani: 'Konkani', kok: 'Konkani', कोंकणी: 'Konkani',
    maithili: 'Maithili', mai: 'Maithili', मैथिली: 'Maithili',
    dogri: 'Dogri', doi: 'Dogri', डोगरी: 'Dogri',
    bodo: 'Bodo', brx: 'Bodo', बोडो: 'Bodo',
    santali: 'Santali', sat: 'Santali', संथाली: 'Santali', ᱥᱟᱱᱛᱟᱲᱤ: 'Santali',
    manipuri: 'Manipuri', meitei: 'Manipuri', mni: 'Manipuri', मणिपुरी: 'Manipuri',
    kashmiri: 'Kashmiri', ks: 'Kashmiri', कश्मीरी: 'Kashmiri',
    sindhi: 'Sindhi', sd: 'Sindhi', سنڌي: 'Sindhi',
  };

  let normalizedLang = 'English';
  for (const [k, v] of Object.entries(langKeyMap)) {
    if (rawLang.includes(k)) {
      normalizedLang = v;
      break;
    }
  }

  const trimmedKey = String(key || '').trim();

  // 1. Check UNIVERSAL_22_LANG_MAP exact match
  if (UNIVERSAL_22_LANG_MAP && UNIVERSAL_22_LANG_MAP[trimmedKey] && UNIVERSAL_22_LANG_MAP[trimmedKey][normalizedLang]) {
    let result = UNIVERSAL_22_LANG_MAP[trimmedKey][normalizedLang];
    if (replacements) {
      Object.entries(replacements).forEach(([rk, rv]) => {
        result = result.replace(new RegExp(`\\{\\s*${rk}\\s*\\}`, 'g'), String(rv));
      });
    }
    return result;
  }

  // 2. Check UNIVERSAL_22_LANG_MAP case-insensitive match
  if (UNIVERSAL_22_LANG_MAP) {
    const lowerKey = trimmedKey.toLowerCase();
    for (const [uKey, uMap] of Object.entries(UNIVERSAL_22_LANG_MAP)) {
      if (uKey.toLowerCase() === lowerKey && uMap && uMap[normalizedLang]) {
        let result = uMap[normalizedLang];
        if (replacements) {
          Object.entries(replacements).forEach(([rk, rv]) => {
            result = result.replace(new RegExp(`\\{\\s*${rk}\\s*\\}`, 'g'), String(rv));
          });
        }
        return result;
      }
    }
  }

  // 3. Check regional tool locales
  let dict: Record<string, string> = TOOL_LOCALES;
  if (normalizedLang === 'Hindi') dict = HINDI_TOOL_LOCALES;
  else if (normalizedLang === 'Marathi') dict = MARATHI_TOOL_LOCALES;
  else if (normalizedLang === 'Gujarati') dict = GUJARATI_TOOL_LOCALES;
  else if (normalizedLang === 'Bengali') dict = BENGALI_TOOL_LOCALES;
  else if (normalizedLang === 'Tamil') dict = TAMIL_TOOL_LOCALES;
  else if (normalizedLang === 'Telugu') dict = TELUGU_TOOL_LOCALES;
  else if (normalizedLang === 'Kannada') dict = KANNADA_TOOL_LOCALES;
  else if (normalizedLang === 'Malayalam') dict = MALAYALAM_TOOL_LOCALES;
  else if (normalizedLang === 'Punjabi') dict = PUNJABI_TOOL_LOCALES;
  else if (normalizedLang === 'Odia') dict = ODIA_TOOL_LOCALES;
  else if (normalizedLang === 'Urdu') dict = URDU_TOOL_LOCALES;
  else if (normalizedLang === 'Assamese') dict = ASSAMESE_TOOL_LOCALES;
  else if (normalizedLang === 'Sanskrit') dict = SANSKRIT_TOOL_LOCALES;
  else if (normalizedLang === 'Nepali') dict = NEPALI_TOOL_LOCALES;
  else if (normalizedLang === 'Konkani') dict = KONKANI_TOOL_LOCALES;
  else if (normalizedLang === 'Maithili') dict = MAITHILI_TOOL_LOCALES;
  else if (normalizedLang === 'Dogri') dict = DOGRI_TOOL_LOCALES;
  else if (normalizedLang === 'Bodo') dict = BODO_TOOL_LOCALES;
  else if (normalizedLang === 'Santali') dict = SANTALI_TOOL_LOCALES;
  else if (normalizedLang === 'Manipuri') dict = MANIPURI_TOOL_LOCALES;
  else if (normalizedLang === 'Kashmiri') dict = KASHMIRI_TOOL_LOCALES;
  else if (normalizedLang === 'Sindhi') dict = SINDHI_TOOL_LOCALES;

  let val = dict[key] || dict[trimmedKey];

  // 4. Try global TRANSLATIONS
  if (!val && TRANSLATIONS && TRANSLATIONS[normalizedLang]) {
    const globalDict = TRANSLATIONS[normalizedLang];
    if (globalDict[key] && typeof globalDict[key] === 'string') {
      val = globalDict[key];
    }
  }

  // 5. Fallback to Hindi if missing in regional dict
  if (!val && normalizedLang !== 'Hindi' && HINDI_TOOL_LOCALES && HINDI_TOOL_LOCALES[key]) {
    val = HINDI_TOOL_LOCALES[key];
  }

  // 6. Fallback to English TOOL_LOCALES
  if (!val && TOOL_LOCALES && TOOL_LOCALES[key]) {
    val = TOOL_LOCALES[key];
  }

  // 7. Fallback string
  if (!val) {
    val = fallback || key;
  }

  if (replacements && typeof replacements === 'object') {
    Object.entries(replacements).forEach(([rk, rv]) => {
      val = val.replace(new RegExp(`\\{\\s*${rk}\\s*\\}`, 'g'), String(rv));
    });
  }

  return val;
}

export const getToolTranslation = tTool;

export function getLocalizedCourtPrepStructure(
  arg1?: any,
  arg2?: any,
  arg3?: any,
  arg4?: any
): any {
  let tabId = typeof arg1 === 'string' ? arg1 : '';
  let language = typeof arg2 === 'string' ? arg2 : (typeof arg1 === 'string' ? arg1 : 'English');
  let caseType = arg3;
  let fileName = arg4;

  if (typeof arg2 === 'object' && arg2 !== null) {
    language = arg1;
    const defaultStructure = arg2;
    if (Array.isArray(defaultStructure)) {
      return defaultStructure.map(item => ({
        ...item,
        title: item.title ? tTool(language, item.title, item.title) : item.title,
        heading: item.heading ? tTool(language, item.heading, item.heading) : item.heading,
        description: item.description ? tTool(language, item.description, item.description) : item.description,
      }));
    }
  }

  const lang = String(language || 'English');
  const tTitle = tTool(lang, tabId, tabId);
  return `### ⚖️ ${tTitle} (${lang})\n\n**${tTool(lang, 'Case Type', 'Case Type')}:** ${caseType || 'General'}\n**${tTool(lang, 'Document', 'Document')}:** ${fileName || 'Court Brief'}\n\n1. **${tTool(lang, 'Key Legal Issues', 'Key Legal Issues')}**: ${tTool(lang, 'Issue analysis generated in selected language.', 'Issue analysis generated in selected language.')}\n2. **${tTool(lang, 'Statutory Authority', 'Statutory Authority')}**: ${tTool(lang, 'Relevant sections and acts.', 'Relevant sections and acts.')}\n3. **${tTool(lang, 'Strategic Submissions', 'Strategic Submissions')}**: ${tTool(lang, 'Oral and written arguments.', 'Oral and written arguments.')}`;
}

export function getLocalizedTemplateStructure(
  arg1?: any,
  arg2?: any,
  arg3?: any
): any {
  let templateId = typeof arg1 === 'string' ? arg1 : 'legalNotice';
  let language = typeof arg2 === 'string' ? arg2 : 'English';
  let getFieldValue = typeof arg3 === 'function' ? arg3 : () => '';

  if (typeof arg2 === 'object' && arg2 !== null) {
    language = arg1;
    const defaultStructure = arg2;
    if (Array.isArray(defaultStructure)) {
      return defaultStructure.map(item => ({
        ...item,
        name: item.name ? tTool(language, item.name, item.name) : item.name,
        title: item.title ? tTool(language, item.title, item.title) : item.title,
        description: item.description ? tTool(language, item.description, item.description) : item.description,
      }));
    }
  }

  const lang = String(language || 'English');
  const sender = (typeof getFieldValue === 'function' && (getFieldValue('senderName') || getFieldValue('clientName'))) || '[Sender Name]';
  const recipient = (typeof getFieldValue === 'function' && (getFieldValue('recipientName') || getFieldValue('oppositeParty'))) || '[Recipient Name]';
  const date = new Date().toLocaleDateString();

  return `LEGAL NOTICE / LEGAL DRAFT (${lang.toUpperCase()})\nDate: ${date}\n\nFROM: ${sender}\nTO: ${recipient}\n\nSUBJECT: ${tTool(lang, 'Legal Notice for Claim and Compliance', 'Legal Notice for Claim and Compliance')}\n\n1. ${tTool(lang, 'Notice is hereby served under applicable Indian laws.', 'Notice is hereby served under applicable Indian laws.')}\n2. ${tTool(lang, 'You are requested to fulfill the terms within 15 days of receipt of this notice.', 'You are requested to fulfill the terms within 15 days of receipt of this notice.')}\n3. ${tTool(lang, 'Failure to comply will result in appropriate legal proceedings.', 'Failure to comply will result in appropriate legal proceedings.')}\n\nSincerely,\n${sender}`;
}
